package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import org.json.*;
public final class ObjScanlineInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();PrintStream original=System.out;try{File dir=getTargetContext().getFilesDir();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream capture=new PrintStream(bytes,true,"UTF-8")){System.setOut(capture);ObjScanlineTest.main(new String[]{new File(dir,"obj-scanline-cases.bin").getPath()});}finally{System.setOut(original);}String verification=bytes.toString("UTF-8").trim();if(!verification.startsWith("PASS_OBJ_SCANLINE "))throw new AssertionError("Verifier did not complete");JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_OBJ_SCANLINE");report.put("verification",verification);report.put("api",Build.VERSION.SDK_INT);report.put("game_steps",0);report.put("gpu_integration",false);try(FileOutputStream out=getTargetContext().openFileOutput("obj-scanline-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable failure){System.setOut(original);android.util.Log.e("NFSUGObjScanline","Failed",failure);result.putString("stream","FAIL: "+failure);finish(Activity.RESULT_CANCELED,result);}}
}
